"""Minimal Minesweeper engine: 9x9 board, 10 mines, first click safe."""

import random


class Minesweeper:
    SIZE = 9
    MINE_COUNT = 10

    def __init__(self, seed=None):
        self._rng = random.Random(seed)
        self.mines = set()
        self.revealed = set()
        self.flagged = set()
        self.started = False
        self.lost = False
        self.won = False

    # ------------------------------------------------------------------ #
    # Helpers
    # ------------------------------------------------------------------ #

    @staticmethod
    def _in_bounds(r, c):
        return 0 <= r < Minesweeper.SIZE and 0 <= c < Minesweeper.SIZE

    def _neighbors(self, r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if self._in_bounds(nr, nc):
                    yield nr, nc

    def adjacent_mines(self, r, c):
        """Number of mines in the 8 neighbors of (r, c)."""
        return sum(1 for n in self._neighbors(r, c) if n in self.mines)

    # ------------------------------------------------------------------ #
    # Mine placement (after the first reveal)
    # ------------------------------------------------------------------ #

    def _place_mines(self, center):
        """Place mines with rng, then deterministically relocate any mine
        that fell into the first-click neighborhood (center + 8 neighbors).

        Relocation rule: scan the board row-major and put the offending
        mine into the first cell that is outside the safe zone and not
        already occupied by another mine.
        """
        safe = {center} | set(self._neighbors(*center))
        picks = [divmod(i, self.SIZE)
                 for i in self._rng.sample(range(self.SIZE * self.SIZE),
                                           self.MINE_COUNT)]

        free_cells = ((r, c)
                      for r in range(self.SIZE)
                      for c in range(self.SIZE)
                      if (r, c) not in safe)

        mines = set()
        for cell in picks:
            if cell not in safe and cell not in mines:
                mines.add(cell)
            else:  # offending pick -> deterministic relocation
                for cand in free_cells:
                    if cand not in mines:
                        mines.add(cand)
                        break
        self.mines = mines

    # ------------------------------------------------------------------ #
    # Moves
    # ------------------------------------------------------------------ #

    def toggle_flag(self, r, c):
        """Flag/unflag an unrevealed cell. No-op otherwise."""
        if self.lost or self.won or not self._in_bounds(r, c):
            return
        if (r, c) in self.revealed:
            return
        self.flagged.symmetric_difference_update({(r, c)})

    def reveal(self, r, c):
        """Reveal a cell; flood-fills zero-adjacency regions."""
        if self.lost or self.won or not self._in_bounds(r, c):
            return
        if (r, c) in self.flagged or (r, c) in self.revealed:
            return  # flagged cells are protected; already-revealed is a no-op

        if not self.started:
            self._place_mines((r, c))  # mines placed AFTER the first reveal
            self.started = True

        if (r, c) in self.mines:
            self.revealed.add((r, c))
            self.lost = True
            return

        stack = [(r, c)]
        while stack:
            cell = stack.pop()
            if cell in self.revealed or cell in self.mines:
                continue
            self.revealed.add(cell)
            if self.adjacent_mines(*cell) == 0:
                stack.extend(self._neighbors(*cell))

        self._check_win()

    def _check_win(self):
        safe_total = self.SIZE * self.SIZE - self.MINE_COUNT
        if len(self.revealed) >= safe_total:
            self.won = True

